void* handle = dlopen("libutility.so", RTLD_LAZY);
if (!handle) {
    fprintf(stderr, "Error loading library: %s\n", dlerror());
    return;
}

// Define the function signature expected from the library
typedef int (*math_func_t)(int, int);

// Get the symbol address
math_func_t func = (math_func_t)dlsym(handle, "add_values");

const char* dlsym_error = dlerror();
if (dlsym_error) {
    fprintf(stderr, "Cannot find symbol: %s\n", dlsym_error);
    dlclose(handle);
    return;
}

int result = func(10, 5);
// result is 15 (assuming library implements int add_values(int a, int b))

dlclose(handle);
